Leia a rota abaixo (Express 4 + `pg` + nodemailer). Ela tem HTTP, SQL, regra de negócio e envio de e-mail na mesma função — impossível testar a regra do desconto sem banco, sem SMTP e sem esperar até segunda-feira.

```
const express = require('express')
const { pool } = require('./db')
const { transporter } = require('./mail')
const app = express()

app.post('/pedidos/:id/fechar', async (req, res) => {
  const { rows } = await pool.query('SELECT * FROM itens WHERE pedido_id = $1', [req.params.id])
  if (rows.length === 0) return res.status(422).json({ erro: 'pedido vazio' })
  const total = rows.reduce((s, i) => s + i.qtd * i.preco_centavos, 0)
  const desconto = new Date().getDay() === 1 ? Math.round(total * 0.1) : 0   // segunda: 10% off
  await pool.query(
    'UPDATE pedidos SET status = $1, total = $2, fechado_em = $3 WHERE id = $4',
    ['FECHADO', total - desconto, new Date(), req.params.id]
  )
  await transporter.sendMail({ to: req.body.email, subject: 'Pedido fechado', text: `Total: ${total - desconto}` })
  res.json({ total: total - desconto })
})
```

Você vai extrair a regra para uma função de domínio `fecharPedido(pedidoId)` criada por uma fábrica `criarFecharPedido({ ... })`. No papel, liste cada coisa que a função usa e classifique: **porta** (efeito externo ou variação — recebe pela fábrica) ou **detalhe puro** (fica dentro da regra).

Entregue: marque TODAS as dependências que viram porta (são injetadas pela fábrica).

exercicios.solucao:
**Portas: `pool.query` (banco), `new Date()` (relógio) e `transporter.sendMail` (rede/SMTP).** `Math.round` e `reduce` são computação pura, determinística, sem efeito externo — inverter isso é cerimônia, não arquitetura.

A forma em Node, sem framework de DI:

```
function criarFecharPedido({ pedidos, relogio, notificador }) {
  return async function fecharPedido(pedidoId, email) {
    const itens = await pedidos.itens(pedidoId)
    if (itens.length === 0) throw new PedidoVazio(pedidoId)
    const total = itens.reduce((s, i) => s + i.qtd * i.precoCentavos, 0)
    const agora = relogio.agora()
    const desconto = agora.getDay() === 1 ? Math.round(total * 0.1) : 0
    const liquido = total - desconto
    await pedidos.fechar(pedidoId, { total: liquido, fechadoEm: agora })
    await notificador.pedidoFechado({ email, total: liquido })
    return { total: liquido }
  }
}
```

Repare que as portas falam a linguagem do domínio (`pedidos.itens`, `pedidos.fechar`, `notificador.pedidoFechado`), não da tecnologia: uma porta `db.query(sql)` não inverteu nada — o domínio continuaria sabendo SQL. Repare também no que saiu da função: `req`/`res` e o `422`. O Express é o adaptador de ENTRADA; ele chama `fecharPedido` e traduz `PedidoVazio` em 422. O domínio não conhece HTTP, então ele não é 'injetado' — é removido. Quem monta tudo é um `composicao.js` na raiz: `criarFecharPedido({ pedidos: repositorioPG(pool), relogio: { agora: () => new Date() }, notificador: emailNodemailer(transporter) })`.

O ganho em números: a suíte da regra roda em milissegundos com `{ agora: () => new Date('2026-09-14T12:00:00Z') }` (uma segunda-feira) e um repositório em memória; a versão original exige PG + SMTP de mentira + esperar o dia certo. E o e-mail dentro da transação de negócio é o próximo problema (falhou o SMTP, o pedido já está FECHADO no banco e o cliente recebe 500) — a saída sênior é trocar `notificador` por um evento `PedidoFechado` em outbox, assunto do exercício de refatoração.

```
// dominio/fecharPedido.js
class PedidoVazio extends Error {
  constructor(id) { super(`pedido ${id} sem itens`); this.name = 'PedidoVazio'; this.pedidoId = id }
}

function criarFecharPedido({ pedidos, relogio, eventos }) {
  return async function fecharPedido(pedidoId) {
    const itens = await pedidos.itens(pedidoId)
    if (itens.length === 0) throw new PedidoVazio(pedidoId)
    const total = itens.reduce((s, i) => s + i.qtd * i.precoCentavos, 0)
    const agora = relogio.agora()
    const desconto = agora.getDay() === 1 ? Math.round(total * 0.1) : 0
    const liquido = total - desconto
    await pedidos.fechar(pedidoId, { total: liquido, fechadoEm: agora })
    await eventos.publicar({ tipo: 'PedidoFechado', v: 1, pedidoId, total: liquido, em: agora.toISOString() })
    return { total: liquido }
  }
}
module.exports = { criarFecharPedido, PedidoVazio }
```

```
// dominio/fecharPedido.test.js
const { test } = require('node:test')
const assert = require('node:assert/strict')
const { criarFecharPedido, PedidoVazio } = require('./fecharPedido')

function montar({ itens, data }) {
  const publicados = []
  const fechados = []
  const fechar = criarFecharPedido({
    pedidos: { itens: async () => itens, fechar: async (id, dados) => { fechados.push({ id, ...dados }) } },
    relogio: { agora: () => new Date(data) },
    eventos: { publicar: async (e) => { publicados.push(e) } },
  })
  return { fechar, publicados, fechados }
}
const dois = [{ qtd: 2, precoCentavos: 5000 }]

test('segunda aplica 10%', async () => {
  const { fechar } = montar({ itens: dois, data: '2026-09-14T12:00:00Z' })
  assert.equal((await fechar(1)).total, 9000)
})
test('terça não aplica', async () => {
  const { fechar } = montar({ itens: dois, data: '2026-09-15T12:00:00Z' })
  assert.equal((await fechar(1)).total, 10000)
})
test('pedido vazio lança e não publica', async () => {
  const { fechar, publicados, fechados } = montar({ itens: [], data: '2026-09-15T12:00:00Z' })
  await assert.rejects(() => fechar(1), PedidoVazio)
  assert.equal(publicados.length, 0)
  assert.equal(fechados.length, 0)
})
test('publica 1 PedidoFechado com o líquido', async () => {
  const { fechar, publicados } = montar({ itens: dois, data: '2026-09-14T12:00:00Z' })
  await fechar(7)
  assert.equal(publicados.length, 1)
  assert.deepEqual({ tipo: publicados[0].tipo, pedidoId: publicados[0].pedidoId, total: publicados[0].total }, { tipo: 'PedidoFechado', pedidoId: 7, total: 9000 })
})
```

`node --test`: 4 testes, `duration_ms` da suíte tipicamente 40–120 ms; `time` total ≈ 0,2–0,4 s (é o boot do Node). Comparado com a versão original — subir PG, criar tabelas, mockar SMTP — a suíte roda a cada save em vez de antes do commit.

**E-mail e outbox.** O e-mail deixou de ser responsabilidade de `fecharPedido`: quem assina `PedidoFechado` (um consumidor de notificação) manda. Isso já dá isolamento de falha — SMTP fora não devolve 500 no fechamento. Mas com `pedidos.fechar` e `eventos.publicar` em duas idas independentes ao banco/broker há uma janela: o processo cai entre as duas e você tem pedido FECHADO sem evento — cliente sem e-mail, ledger sem lançamento, e ninguém sabe. Outbox fecha a janela: o adaptador PG de `eventos` faz `INSERT INTO outbox (id, tipo, payload, criado_em)` no MESMO `client`/transação do `UPDATE pedidos`; ou os dois commitam ou nenhum. Um worker (`SELECT ... FROM outbox WHERE publicado_em IS NULL FOR UPDATE SKIP LOCKED LIMIT 100`) lê, entrega ao consumidor (e-mail, EventEmitter, Redis Stream) e marca. Como o worker pode morrer depois de entregar e antes de marcar, o consumidor tem que ser idempotente (chave `evento.id` já processado → ignora). No domínio isso aparece como uma porta de unidade de trabalho — `pedidos.transacao(async (tx) => { await tx.fechar(...); await tx.publicar(...) })` — e o adaptador em memória continua sendo dois arrays; a regra não mudou uma linha.

O teste de sanidade da Clean Architecture vale aqui: `grep -E "require\('(express|pg|nodemailer)'\)" dominio/*.js` tem que voltar vazio. Se voltar algo, a regra foi violada, não importa o nome da pasta.

Configuração mínima que passa no lab limpo e falha nas duas violações:

```
// .dependency-cruiser.cjs
module.exports = {
  forbidden: [
    {
      name: 'sem-import-profundo',
      comment: 'De fora de um módulo, só o index.js dele pode ser importado',
      severity: 'error',
      from: { path: '^src/modules/([^/]+)/' },
      to: { path: '^src/modules/', pathNot: '^src/modules/$1/|^src/modules/[^/]+/index\\.js$' },
    },
    {
      name: 'sem-import-profundo-de-fora-dos-modulos',
      severity: 'error',
      from: { pathNot: '^src/modules/' },
      to: { path: '^src/modules/', pathNot: '^src/modules/[^/]+/index\\.js$' },
    },
    {
      name: 'dominio-sem-infra',
      comment: 'Domínio não conhece HTTP, banco, cache nem rede',
      severity: 'error',
      from: { path: '^src/modules/[^/]+/dominio/' },
      to: { path: '^src/http/|node_modules/(express|pg|ioredis|axios)/' },
    },
    { name: 'no-circular', severity: 'error', from: {}, to: { circular: true } },
  ],
  options: {
    doNotFollow: { path: 'node_modules' },
    tsPreCompilationDeps: false,
    enhancedResolveOptions: { exportsFields: ['exports'], conditionNames: ['import', 'require', 'node', 'default'] },
  },
}
```

A regra de import profundo precisa de duas versões porque um grupo de captura só funciona em `path` (não em `pathNot`): a primeira cobre 'módulo A importando o interior de B' (permite o próprio interior via `$1`), a segunda cobre 'quem não é módulo (http, scripts) importando interior de qualquer módulo'.

